1	import { EMPTY, merge } from "rxjs";
2	import type { Observable } from "rxjs";
3	import { catchError } from "rxjs/operators";
4	import type { DeviceModel } from "@ledgerhq/types-devices";
5	import Transport from "@ledgerhq/hw-transport";
6	import { TraceContext, trace } from "@ledgerhq/logs";
7	import { CantOpenDevice } from "@ledgerhq/errors";
8	
9	export const LOG_TYPE = "hw";
10	
11	export type DeviceEvent = {
12	  type: "add" | "remove";
13	  id: string;
14	  name: string;
15	  deviceModel?: DeviceModel | null;
16	  wired?: boolean;
17	};
18	
19	export type Discovery = Observable<DeviceEvent>;
20	// NB open/close/disconnect semantic will have to be refined...
21	export type TransportModule = {
22	  // unique transport name that identify the transport module
23	  id: string;
24	  /*
25	   * Opens a device by an id, this id must be unique across all modules
26	   * you can typically prefix it with `something|` that identify it globally
27	   * returns falsy if the transport module can't handle this id
28	   * here, open means we want to START doing something with the transport
29	   *
30	   * @param id
31	   * @param timeoutMs Optional timeout that can be used by the Transport implementation when opening a communication channel
32	   * @param context Optional context to be used in logs/tracing
33	   */
34	  open: (
35	    id: string,
36	    timeoutMs?: number,
37	    context?: TraceContext,
38	  ) => Promise<Transport> | null | undefined;
39	  // here, close means we want to STOP doing something with the transport
40	  close?: (transport: Transport, id: string) => Promise<void> | null | undefined;
41	  // disconnect/interrupt a device connection globally
42	  // returns falsy if the transport module can't handle this id
43	  disconnect: (id: string) => Promise<void> | null | undefined;
44	
45	  /**
46	   * Determines whether an auto-disconnect can happen at this time or not.
47	   *
48	   * Currently only used by TransportNodeHid
49	   */
50	  setAllowAutoDisconnect?: (
51	    transport: Transport,
52	    id: string,
53	    allow: boolean,
54	  ) => Promise<void> | null | undefined;
55	
56	  // optional observable that allows to discover a transport
57	  discovery?: Discovery;
58	};
59	
60	const modules: TransportModule[] = [];
61	export const registerTransportModule = (module: TransportModule): void => {
62	  modules.push(module);
63	};
64	
65	export const discoverDevices = (
66	  accept: (module: TransportModule) => boolean = () => true,
67	): Discovery => {
68	  const all: Discovery[] = [];
69	
70	  for (let i = 0; i < modules.length; i++) {
71	    const m = modules[i];
72	
73	    if (m.discovery && accept(m)) {
74	      all.push(m.discovery);
75	    }
76	  }
77	
78	  return merge(
79	    ...all.map(o =>
80	      o.pipe(
81	        catchError(error => {
82	          trace({ type: LOG_TYPE, message: "One Transport provider failed", data: { error } });
83	          return EMPTY;
84	        }),
85	      ),
86	    ),
87	  );
88	};
89	
90	/**
91	 * Tries to call `open` on the 1st matching registered transport implementation
92	 *
93	 * An optional timeout `timeoutMs` can be set. It is/can be used in 2 different places:
94	 * - A `timeoutMs` timeout is applied directly in this function: racing between the matching Transport opening and this timeout
95	 * - And the `timeoutMs` parameter is also passed to the `open` method of the transport module so each transport implementation
96	 *  can make use of that parameter and implement their timeout mechanism internally
97	 *
98	 * Why using it in 2 places ?
99	 * As there is no easy way to abort a Promise (returned by `open`), the Transport will continue to try connecting to the device
100	 * even if this function timeout was reached. But certain Transport implementations can also use this timeout to try to stop
101	 * the connection attempt internally.
102	 *
103	 * @param deviceId
104	 * @param timeoutMs Optional timeout that limits in time the open attempt of the matching registered transport.
105	 * @param context Optional context to be used in logs
106	 * @returns a Promise that resolves to a Transport instance, and rejects with a `CantOpenDevice`
107	 *   if no transport implementation can open the device
108	 */
109	export const open = (
110	  deviceId: string,
111	  timeoutMs?: number,
112	  context?: TraceContext,
113	): Promise<Transport> => {
114	  // The first registered Transport (TransportModule) accepting the given device will be returned.
115	  // The open is not awaited, the check on the device is done synchronously.
116	  // A TransportModule can check the prefix of the device id to guess if it should use USB or not on LLM for ex.
117	  for (let i = 0; i < modules.length; i++) {
118	    const m = modules[i];
119	    const p = m.open(deviceId, timeoutMs, context);
120	    if (p) {
121	      trace({
122	        type: LOG_TYPE,
123	        message: `Found a matching Transport: ${m.id}`,
124	        context,
125	        data: { timeoutMs },
126	      });
127	
128	      if (!timeoutMs) {
129	        return p;
130	      }
131	
132	      let timer: ReturnType<typeof setTimeout> | null = null;
133	
134	      // Throws CantOpenDevice on timeout, otherwise returns the transport.
135	      // Important: with Javascript Promise, when one promise finishes,
136	      // the other will still continue, even if its return value will be discarded.
137	      return Promise.race([
138	        p.then(transport => {
139	          // Necessary to stop the ongoing timeout
140	          if (timer) {
141	            clearTimeout(timer);
142	          }
143	
144	          return transport;
145	        }),
146	        new Promise((_resolve, reject) => {
147	          timer = setTimeout(() => {
148	            trace({
149	              type: LOG_TYPE,
150	              message: `Could not open registered transport ${m.id} on ${deviceId}, timed out after ${timeoutMs}ms`,
151	              context,
152	            });
153	
154	            return reject(new CantOpenDevice(`Timeout while opening device on transport ${m.id}`));
155	          }, timeoutMs);
156	        }),
157	      ]) as Promise<Transport>;
158	    }
159	  }
160	
161	  return Promise.reject(new CantOpenDevice(`Cannot find registered transport to open ${deviceId}`));
162	};
163	
164	export const close = (
165	  transport: Transport,
166	  deviceId: string,
167	  context?: TraceContext,
168	): Promise<void> => {
169	  trace({ type: LOG_TYPE, message: "Trying to close transport", context });
170	
171	  // Tries to call close on the registered TransportModule implementation first
172	  for (let i = 0; i < modules.length; i++) {
173	    const m = modules[i];
174	    const p = m.close && m.close(transport, deviceId);
175	    if (p) {
176	      trace({
177	        type: LOG_TYPE,
178	        message: `Closing transport via registered module: ${m.id}`,
179	        context,
180	      });
181	      return p;
182	    }
183	  }
184	
185	  trace({ type: LOG_TYPE, message: `Closing transport via the transport implementation`, context });
186	  // Otherwise fallbacks on the transport implementation of close directly
187	  return transport.close();
188	};
189	export const setAllowAutoDisconnect = (
190	  transport: Transport,
191	  deviceId: string,
192	  allow: boolean,
193	): Promise<void> | null | undefined => {
194	  for (let i = 0; i < modules.length; i++) {
195	    const m = modules[i];
196	    const p = m.setAllowAutoDisconnect && m.setAllowAutoDisconnect(transport, deviceId, allow);
197	    if (p) return p;
198	  }
199	};
200	
201	export const disconnect = (deviceId: string): Promise<void> => {
202	  for (let i = 0; i < modules.length; i++) {
203	    const dis = modules[i].disconnect;
204	    const p = dis(deviceId);
205	
206	    if (p) {
207	      return p;
208	    }
209	  }
210	
211	  return Promise.reject(new Error(`Can't find handler to disconnect ${deviceId}`));
212	};
